def choose_move(observation):
    dx = 0
    dy = 0

    pos = observation.get('self_position', {})
    x = pos.get('x', 0)
    y = pos.get('y', 0)

    grid = observation.get('grid_width', None)
    if grid is None:
        grid = observation.get('grid', {})
    gw = observation.get('grid_width', 0)
    gh = observation.get('grid_height', 0)
    if gw == 0:
        gw = grid if isinstance(grid, int) else observation.get('grid', {}).get('width', 0)
    if gh == 0:
        gh = observation.get('grid', {}).get('height', 0)

    resources = observation.get('resources', [])
    opp = observation.get('opponent_position', {})
    ox = opp.get('x', None)
    oy = opp.get('y', None)

    center_x = gw // 2
    center_y = gh // 2

    best_rx, best_ry = None, None
    best_dist = 10**9
    for r in resources or []:
        rx = r.get('x', 0)
        ry = r.get('y', 0)
        d = abs(rx - x) + abs(ry - y)
        if d < best_dist:
            best_dist = d
            best_rx, best_ry = rx, ry

    if best_rx is not None:
        dx = 0
        dy = 0
        if best_rx > x:
            dx = 1
        elif best_rx < x:
            dx = -1
        if best_ry > y:
            dy = 1
        elif best_ry < y:
            dy = -1
        return [dx, dy]

    if ox is not None and oy is not None:
        dx = 0
        dy = 0
        if ox > x:
            dx = 1
        elif ox < x:
            dx = -1
        if oy > y:
            dy = 1
        elif oy < y:
            dy = -1
        return [dx, dy]

    if x < center_x:
        dx = 1
    elif x > center_x:
        dx = -1

    if y < center_y:
        dy = 1
    elif y > center_y:
        dy = -1

    return [dx, dy]
